public void testToDateTimeAtCurrentTime_1_oe() {
    YearMonthDay base = new YearMonthDay(2005, 6, 9, COPTIC_PARIS); // PARIS irrelevant
    DateTime dt = new DateTime(2004, 6, 9, 6, 7, 8, 9);
