public void testCompareTo_5_oe() {
    LocalDate test1 = new LocalDate(2005, 6, 2);
    LocalDate test1a = new LocalDate(2005, 6, 2);

    LocalDate test2 = new LocalDate(2005, 7, 2);
    assertEquals(0, test1a.compareTo(test1));
}

focal_method:
@Override
    public int compareTo(ReadablePartial partial) {
        // override to perform faster
        if (this == partial) {
            return 0;
        }
        if (partial instanceof LocalDate) {
            LocalDate other = (LocalDate) partial;
            if (iChronology.equals(other.iChronology)) {
                return (iLocalMillis < other.iLocalMillis ? -1 :
                            (iLocalMillis == other.iLocalMillis ? 0 : 1));

            }
        }
        return super.compareTo(partial);
    }

