        StringBuilder buf = new StringBuilder(requirePrinter().estimatePrintedLength());
        try {
            printTo((Appendable) buf, instant);
        } catch (IOException ex) {
            // StringBuilder does not throw IOException
        }
        return buf.toString();
    }

test_prefix:
public void testCustomDateTimePrinter_1_oe() {
    DateTimePrinter printer = new DateTimeFormatterBuilder()
            .append(new CustomDateTimePrinter())
            .appendLiteral(' ')
            .appendYear(4, 8)
            .toPrinter();

    StringBuffer buffer = new StringBuffer();
    long instant = new DateTime(2017, 1, 1, 0, 0, 0, ISO_UTC).getMillis();
    printer.printTo(buffer, instant, ISO_UTC, 0, UTC, Locale.ENGLISH);

    assertEquals("2017-01-01T00:00:00.000 ", buffer.toString());
}

focal_method:
public void printTo(StringBuffer buf, ReadableInstant instant) {
        try {
            printTo((Appendable) buf, instant);
        } catch (IOException ex) {
            // StringBuffer does not throw IOException
        }
    }

