test_prefix:
public void test_roundHalfFloor_long_1_oe() {
    BaseDateTimeField field = new MockBaseDateTimeField();
    assertEquals(1372766400000L, field.roundHalfFloor(1372766400000L));
}

focal_method:
@Override
    public long roundHalfFloor(long instant) {
        long floor = roundFloor(instant);
        long ceiling = roundCeiling(instant);

        long diffFromFloor = instant - floor;
        long diffToCeiling = ceiling - instant;

        if (diffFromFloor <= diffToCeiling) {
            // Closer to the floor, or halfway - round floor
            return floor;
        } else {
            return ceiling;
        }
    }

